function mmToUtf8(str){
  var out=[];
  for(var i=0;i<str.length;i++){
    var c=str.charCodeAt(i);
    if(c<0x80){ out.push(c); }
    else if(c<0x800){ out.push(0xC0|(c>>6),0x80|(c&63)); }
    else if(c>=0xD800&&c<=0xDBFF&&i+1<str.length){
      var c2=str.charCodeAt(i+1);
      if(c2>=0xDC00&&c2<=0xDFFF){
        var cp=0x10000+((c-0xD800)<<10)+(c2-0xDC00); i++;
        out.push(0xF0|(cp>>18),0x80|((cp>>12)&63),0x80|((cp>>6)&63),0x80|(cp&63));
      } else out.push(0xE0|(c>>12),0x80|((c>>6)&63),0x80|(c&63));
    }
    else { out.push(0xE0|(c>>12),0x80|((c>>6)&63),0x80|(c&63)); }
  }
  return out;
}
function mmMul32(a,b){
  var ah=(a>>>16)&0xffff, al=a&0xffff;
  return (((ah*b)<<16)+(al*b))>>>0;
}
function mmRotl32(x,r){ return ((x<<r)|(x>>>(32-r)))>>>0; }
function murmur3_32(bytes, seed){
  var h1=(seed||0)>>>0, c1=0xcc9e2d51, c2=0x1b873593;
  var len=bytes.length, nblocks=len>>2, i;
  for(i=0;i<nblocks;i++){
    var k1=(bytes[i*4]|(bytes[i*4+1]<<8)|(bytes[i*4+2]<<16)|(bytes[i*4+3]<<24))>>>0;
    k1=mmMul32(k1,c1); k1=mmRotl32(k1,15); k1=mmMul32(k1,c2);
    h1=(h1^k1)>>>0; h1=mmRotl32(h1,13); h1=(mmMul32(h1,5)+0xe6546b64)>>>0;
  }
  var k=0, tail=nblocks*4, rem=len&3;
  if(rem===3) k=(k^(bytes[tail+2]<<16))>>>0;
  if(rem>=2) k=(k^(bytes[tail+1]<<8))>>>0;
  if(rem>=1){
    k=(k^bytes[tail])>>>0;
    k=mmMul32(k,c1); k=mmRotl32(k,15); k=mmMul32(k,c2);
    h1=(h1^k)>>>0;
  }
  h1=(h1^len)>>>0;
  h1=(h1^(h1>>>16))>>>0; h1=mmMul32(h1,0x85ebca6b);
  h1=(h1^(h1>>>13))>>>0; h1=mmMul32(h1,0xc2b2ae35);
  h1=(h1^(h1>>>16))>>>0;
  return h1>>>0;
}
function murmurStr(str, seed){ return murmur3_32(mmToUtf8(String(str)), seed||0); }
function murmurHex(str, seed){
  var h=murmurStr(str, seed).toString(16);
  while(h.length<8) h='0'+h;
  return h;
}
function murmurBucket(str, seed, n){
  if(!n||n<=0) return { value:null, error:'桶数必须大于 0' };
  return { value: murmurStr(str, seed)%n, error:null };
}
